package desync

// QA v3 byte-effect test (tester-max-2, task t_50f4d699).
//
// For every well-formed fixture in the independent corpus this test drives the
// SHIPPED stream transform end to end (CompileStream -> WrapConn -> Write ->
// Close) and compares the emitted fragment boundaries with the positions that
// the pinned bol-van/zapret v72.9 TLSPos/HttpPos returned for the same bytes.
// The expected positions are read from the oracle output file produced by
// qa3/oracle.c, so no expectation is generated by the implementation.
//
// It also asserts byte preservation: the concatenation of every emitted
// fragment must equal the original block exactly.

import (
	"bytes"
	"context"
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
	"testing"

	"github.com/sagernet/sing-box/option"
	badoption "github.com/sagernet/sing/common/json/badoption"
)

// qa3SkipFixtures are structurally invalid or non-ClientHello/non-HTTP blocks:
// the transform legitimately classifies them as another protocol, which is
// covered by the position comparison instead.
var qa3SkipFixtures = map[string]bool{
	"T_not_client_hello":    true,
	"T_record_version_0304": true,
	"T_rec_len_short":       true,
	"T_rec_len_long":        true,
	"T_tiny_3_bytes":        true,
	"T_tiny_6_bytes":        true,
	"T_hs_len_gt_record":    true,
	"T_hs_len_lt_record":    true,
	"T_ext_len_overrun":     true,
	"T_ext_hdr_trunc":       true,
	"T_trailing_after_record": true,
	"T_second_record_hello":   true,
	"H_method_lower":          true,
	"H_method_8":              true,
	"H_http09":                true,
	"H_leading_crlf":          true,
	"H_leading_lflf":          true,
	"H_weird_leading_upper":   true,
	"H_get_no_host":           true,
}

type qa3Row struct {
	value int
}

func qa3LoadOracle(t *testing.T) map[string]int {
	t.Helper()
	path := os.Getenv("QA3_C_OUT")
	if path == "" {
		t.Skip("QA3_C_OUT not set")
	}
	content, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	values := make(map[string]int)
	for _, line := range strings.Split(string(content), "\n") {
		if strings.TrimSpace(line) == "" {
			continue
		}
		fields := strings.Split(line, "\t")
		if len(fields) != 5 {
			t.Fatalf("bad oracle line %q", line)
		}
		value, err := strconv.Atoi(fields[4])
		if err != nil {
			t.Fatalf("bad oracle value %q", line)
		}
		values[fields[0]+"|"+fields[1]+"|"+fields[2]+"|"+fields[3]] = value
	}
	return values
}

func qa3CompileSplit(t *testing.T, positions []string) *StreamConfig {
	t.Helper()
	config, err := CompileStream([]option.DirectDesyncStreamRule{{
		Methods: badoption.Listable[string]{"split"},
		Split: &option.DirectDesyncStreamSplit{
			SplitPos: badoption.Listable[string](positions),
		},
	}}, "")
	if err != nil {
		t.Fatalf("CompileStream(%v): %v", positions, err)
	}
	config.random = bytes.NewReader(bytes.Repeat([]byte{0x42}, 1<<16))
	return config
}

// qa3Emit writes one block through the shipped transform and returns the
// emitted fragments.
func qa3Emit(t *testing.T, config *StreamConfig, block []byte, port int) [][]byte {
	t.Helper()
	conn := newFakeConn()
	wrapped, err := config.WrapConn(context.Background(), conn, MatchFacts{Port: uint16(port)})
	if err != nil {
		t.Fatalf("WrapConn: %v", err)
	}
	if _, err := wrapped.Write(block); err != nil {
		t.Fatalf("Write: %v", err)
	}
	if err := wrapped.Close(); err != nil {
		t.Fatalf("Close: %v", err)
	}
	return conn.writes
}

func qa3Boundaries(fragments [][]byte) []int {
	boundaries := make([]int, 0, len(fragments))
	total := 0
	for index, fragment := range fragments {
		total += len(fragment)
		if index < len(fragments)-1 {
			boundaries = append(boundaries, total)
		}
	}
	return boundaries
}

// TestQA3EmittedBytesMatchPinnedC is the end-to-end byte check.
func TestQA3EmittedBytesMatchPinnedC(t *testing.T) {
	manifestPath := os.Getenv("QA3_MANIFEST")
	if manifestPath == "" {
		t.Skip("QA3_MANIFEST not set")
	}
	oracle := qa3LoadOracle(t)
	manifest, err := os.ReadFile(manifestPath)
	if err != nil {
		t.Fatal(err)
	}
	markers := []string{"host", "endhost", "sld", "midsld", "endsld"}
	offsets := []int{0, 1, -1, 2, -2}
	checked := 0
	fixtures := 0
	for _, line := range strings.Split(string(manifest), "\n") {
		if strings.TrimSpace(line) == "" {
			continue
		}
		fields := strings.Split(line, "\t")
		name, proto, path := fields[0], fields[1], fields[2]
		if qa3SkipFixtures[name] {
			continue
		}
		block, err := os.ReadFile(path)
		if err != nil {
			t.Fatal(err)
		}
		port := 443
		if proto == "http" {
			port = 80
		}
		fixtures++
		all := make(map[int]bool)
		for _, marker := range markers {
			for _, offset := range offsets {
				key := fmt.Sprintf("%s|%s|%s|%d", name, proto, marker, offset)
				value, ok := oracle[key]
				if !ok {
					t.Fatalf("missing oracle row %s", key)
				}
				if value == 0 || value >= len(block) {
					continue
				}
				all[value] = true
				spelling := marker
				if offset > 0 {
					spelling = fmt.Sprintf("%s+%d", marker, offset)
				} else if offset < 0 {
					spelling = fmt.Sprintf("%s%d", marker, offset)
				}
				fragments := qa3Emit(t, qa3CompileSplit(t, []string{spelling}), block, port)
				if joined := bytes.Join(fragments, nil); !bytes.Equal(joined, block) {
					t.Errorf("%s %s: emitted bytes differ from the input block", name, spelling)
				}
				boundaries := qa3Boundaries(fragments)
				if len(boundaries) != 1 || boundaries[0] != value {
					t.Errorf("%s %s: boundaries %v, pinned C cut %d (fragments %d)",
						name, spelling, boundaries, value, len(fragments))
				}
				checked++
			}
		}
		// One rule carrying every resolvable position at once.
		positions := make([]int, 0, len(all))
		for value := range all {
			positions = append(positions, value)
		}
		sort.Ints(positions)
		spellings := make([]string, 0, len(positions))
		for _, value := range positions {
			// absolute positions are a faithful spelling of the same offset
			if value > 0 {
				spellings = append(spellings, strconv.Itoa(value))
			}
		}
		if len(spellings) > streamMaxSplitPositions {
			spellings = spellings[:streamMaxSplitPositions]
			positions = positions[:streamMaxSplitPositions]
		}
		if len(spellings) == 0 {
			continue
		}
		fragments := qa3Emit(t, qa3CompileSplit(t, spellings), block, port)
		if joined := bytes.Join(fragments, nil); !bytes.Equal(joined, block) {
			t.Errorf("%s multi: emitted bytes differ from the input block", name)
		}
		got := qa3Boundaries(fragments)
		if len(got) != len(positions) {
			t.Errorf("%s multi: %d boundaries %v, want %d from pinned C %v",
				name, len(got), got, len(positions), positions)
			continue
		}
		for index := range got {
			if got[index] != positions[index] {
				t.Errorf("%s multi: boundary[%d] = %d, pinned C = %d", name, index, got[index], positions[index])
			}
		}
	}
	if checked < 400 {
		t.Fatalf("only %d single-position byte checks executed, corpus too small", checked)
	}
	t.Logf("byte-effect: %d fixtures, %d single-position cuts verified", fixtures, checked)
}
